package com.lcl.myaiagent.service.impl;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.lcl.myaiagent.common.ErrorCode; import com.lcl.myaiagent.exception.BusinessException; import com.lcl.myaiagent.mapper.*; import com.lcl.myaiagent.model.po.*; import com.lcl.myaiagent.model.vo.InterviewSessionVO; import com.lcl.myaiagent.service.InterviewService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class InterviewServiceImpl implements InterviewService { private final InterviewSessionMapper sessions; private final InterviewTurnMapper turns; private static final List<String> QUESTIONS=List.of("请介绍 JVM 内存结构，并说明一次常见内存问题的排查过程。","Spring 事务为什么会失效？请结合代理机制说明。","MySQL 索引如何影响查询？如何定位慢 SQL？","Redis 缓存穿透、击穿和雪崩有什么区别？","请用 STAR 法则讲一个你解决过的项目问题。");
 public InterviewSessionVO start(String topic,Integer limit,User user){ InterviewSession s=new InterviewSession();s.setId(UUID.randomUUID().toString());s.setUserId(user.getId());s.setTopic(topic==null||topic.isBlank()?"Java 后端":topic);s.setQuestionLimit(Math.min(Math.max(limit==null?5:limit,1),5));s.setStatus("IN_PROGRESS");sessions.insert(s); addQuestion(s,1);return view(s);}
 @Transactional public InterviewSessionVO answer(String id,String answer,User user){InterviewSession s=session(id,user); InterviewTurn t=turns.selectOne(new LambdaQueryWrapper<InterviewTurn>().eq(InterviewTurn::getSessionId,id).eq(InterviewTurn::getTurnStatus,"ASKED").orderByDesc(InterviewTurn::getTurnNumber).last("limit 1"));if(t==null)throw new BusinessException(ErrorCode.PARAMS_ERROR,"当前没有待回答的问题");if(answer==null||answer.isBlank())throw new BusinessException(ErrorCode.PARAMS_ERROR,"请先提交回答");t.setAnswer(answer.trim());t.setScore(Math.min(100,Math.max(35,answer.trim().length())));t.setFeedback(t.getScore()>=70?"回答覆盖了足够细节；继续补充量化结果和边界条件。":"回答偏短；建议按定义、原理、实践案例和边界条件组织。");t.setTurnStatus("ANSWERED");turns.updateById(t);if(t.getTurnNumber()<s.getQuestionLimit())addQuestion(s,t.getTurnNumber()+1);else {s.setStatus("COMPLETED");sessions.updateById(s);}return view(s);}
 public InterviewSessionVO pause(String id,User u){InterviewSession s=session(id,u);if("IN_PROGRESS".equals(s.getStatus())){s.setStatus("PAUSED");sessions.updateById(s);}return view(s);} public InterviewSessionVO resume(String id,User u){InterviewSession s=session(id,u);if("PAUSED".equals(s.getStatus())){s.setStatus("IN_PROGRESS");sessions.updateById(s);}return view(s);} public InterviewSessionVO get(String id,User u){return view(session(id,u));} public List<InterviewSessionVO> list(User u){return sessions.selectList(new LambdaQueryWrapper<InterviewSession>().eq(InterviewSession::getUserId,u.getId()).orderByDesc(InterviewSession::getCreateTime)).stream().map(this::view).toList();}
 private void addQuestion(InterviewSession s,int number){InterviewTurn t=new InterviewTurn();t.setId(UUID.randomUUID().toString());t.setSessionId(s.getId());t.setTurnNumber(number);t.setQuestion(QUESTIONS.get((number-1)%QUESTIONS.size()));t.setTurnStatus("ASKED");turns.insert(t);} private InterviewSession session(String id,User u){InterviewSession s=sessions.selectOne(new LambdaQueryWrapper<InterviewSession>().eq(InterviewSession::getId,id).eq(InterviewSession::getUserId,u.getId()));if(s==null)throw new BusinessException(ErrorCode.NOT_FOUND_ERROR,"面试不存在或无权访问");return s;} private InterviewSessionVO view(InterviewSession s){InterviewSessionVO v=new InterviewSessionVO();v.setId(s.getId());v.setTopic(s.getTopic());v.setStatus(s.getStatus());v.setQuestionLimit(s.getQuestionLimit());v.setCreateTime(s.getCreateTime());v.setTurns(turns.selectList(new LambdaQueryWrapper<InterviewTurn>().eq(InterviewTurn::getSessionId,s.getId()).orderByAsc(InterviewTurn::getTurnNumber)).stream().map(t->{InterviewSessionVO.Turn x=new InterviewSessionVO.Turn();x.setTurnNumber(t.getTurnNumber());x.setQuestion(t.getQuestion());x.setAnswer(t.getAnswer());x.setFeedback(t.getFeedback());x.setScore(t.getScore());x.setTurnStatus(t.getTurnStatus());return x;}).toList());return v;} }
